    /** A disc with a ring of short rays, for selecting by colour. */
    private val AUTOMATIC = buildString {
        val rays = 16
        append("M")
        for (i in 0 until rays * 2) {
            val r = if (i % 2 == 0) 8.4f else 7f
            val a = Math.PI * i / rays
            append("${12f + r * kotlin.math.cos(a).toFloat()} ${12f + r * kotlin.math.sin(a).toFloat()} ")
        }
        append("z")
    }

    /** The frame the four ways' icons share. */
    private const val FRAME = "M6.6 6.2h10.8a1.6 1.6 0 0 1 1.6 1.6v8.4a1.6 1.6 0 0 1-1.6 1.6H6.6A1.6 1.6 0 0 1 5 16.2V7.8a1.6 1.6 0 0 1 1.6-1.6z"

    /** A checkerboard of squares cut out of a disc. */
    private val CHECKS = buildString {
        for (row in 0 until 4) for (col in 0 until 4) {
            if ((row + col) % 2 == 1) continue
            val x = 5.2f + col * 3.4f
            val y = 5.2f + row * 3.4f
            append("M$x ${y}h3.4v3.4h-3.4z")
        }
    }

    /** One path of an icon: filled (and stroked, to round its corners) or stroked only. */
    private class Part(val d: String, val width: Float, val fill: Boolean, val evenOdd: Boolean = false)

    /** A four-pointed sparkle centred at ([x], [y]), [r] from its centre to a point. */
    private fun star(x: Float, y: Float, r: Float): Part {
        val k = r * 0.28f
        return Part("M$x ${y - r}L${x + k} ${y - k} ${x + r} $y ${x + k} ${y + k} $x ${y + r} ${x - k} ${y + k} ${x - r} $y ${x - k} ${y - k}z", 0.8f, true)
    }

    private fun solid(name: String, vararg paths: String): ImageVector = icon(name, *paths.map { Part(it, 1.2f, true) }.toTypedArray())

    /** A shape filled where its parts overlap too, in a 24 frame. */
    private fun filled(name: String, d: String): ImageVector = icon(name, Part(d, 0f, true))

    private fun outline(name: String, width: Float, vararg paths: String): ImageVector = icon(name, *paths.map { Part(it, width, false) }.toTypedArray())

    /**
     * One of our own icons (docs/icons/STYLE_GUIDE.md, drawn by tools/icons/draw_icons.py) in a [frame] unit
     * square, filled, its knockouts cut out (even-odd).
     */
    private fun ours(name: String, frame: Float, vararg paths: String): ImageVector = ours(name, frame, frame, *paths)

    /** One of our own icons in a [frameWidth] x [frameHeight] unit frame. */
    private fun ours(name: String, frameWidth: Float, frameHeight: Float, vararg paths: String): ImageVector =
        icon(name, *paths.map { Part(it, 0f, true, evenOdd = true) }.toTypedArray(), viewport = frameWidth, viewportHeight = frameHeight)

    /** A Phosphor icon in a [frame] unit square (the frame it is shown in), its paths placed there and filled. */
    private fun phosphor(name: String, frame: Float, vararg paths: String): ImageVector = phosphor(name, frame, frame, *paths)

    /** A Phosphor icon in a [frameWidth] x [frameHeight] unit frame. */
    private fun phosphor(name: String, frameWidth: Float, frameHeight: Float, vararg paths: String): ImageVector =
        icon(name, *paths.map { Part(it, 0f, true) }.toTypedArray(), viewport = frameWidth, viewportHeight = frameHeight)

    /** One of our own outlines in a [frame] unit square, stroked [width] wide. */
    private fun drawn(name: String, frame: Float, width: Float, vararg paths: String): ImageVector =
        icon(name, *paths.map { Part(it, width, false) }.toTypedArray(), viewport = frame)

    private fun icon(name: String, vararg parts: Part, viewport: Float = 24f, viewportHeight: Float = viewport): ImageVector {
        val b = ImageVector.Builder(name = name, defaultWidth = viewport.dp, defaultHeight = viewportHeight.dp, viewportWidth = viewport, viewportHeight = viewportHeight)
        for (p in parts) {
            b.addPath(
                pathData = addPathNodes(p.d),
                pathFillType = if (p.evenOdd) PathFillType.EvenOdd else PathFillType.NonZero,
                fill = if (p.fill) SolidColor(Color.White) else null,
                stroke = if (p.width > 0f) SolidColor(Color.White) else null,
                strokeLineWidth = p.width,
                strokeLineCap = StrokeCap.Round,
                strokeLineJoin = StrokeJoin.Round,
            )
        }
        return b.build()
    }
}
